function gsDateToISO(value) {
  if (!value || isNaN(value)) return "";
  const epoch = new Date(Date.UTC(1899, 11, 30));
  epoch.setDate(epoch.getDate() + Number(value));
  return epoch.toISOString().split("T")[0];
}

function normalizeCity(raw) {
  const c = String(raw || "").trim();
  const lower = c.toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  // Todas las variantes de Estado de México → valor exacto en Monday
  if (
    lower === "estado mexico" ||
    lower === "estado de mexico" ||
    lower === "edomex" ||
    lower === "edo mexico" ||
    lower === "edo. mexico" ||
    lower === "edo. de mexico" ||
    lower === "estado de mex" ||
    lower === "estado mex"
  ) {
    return "Estado de México";
  }

  return c;
}

return items.map(item => {
  const j = item.json;
  return {
    json: {
      product:           j["Product"]        || "",
      company_id:        j["ID EMPRESA"]      || "",
      customer_name:     j["Customer name"]  || "",
      address:           j["Address"]        || "",
      zipcode:           j["Zipcode"]        || "",
      telephone:         j["telephone"]      || "",
      mobile:            j["Mobile"]         || "",
      contact_person:    j["Contact person"] || "",
      email:             j["e-mail"]         || "",
      url_web:           j["URL Web"]        || "",
      city:              normalizeCity(j["City"]),
      id_venue:          String(j["ID EMPRESA"] || ""),
      end_contract_date: gsDateToISO(j["End Contract Date"]),
      rw_date:           gsDateToISO(j["RW date"])
    }
  };
});

const TARGET_MONTH = $input.first().json.Month;
const TARGET_YEAR  = $input.first().json.Year;

const filtrados = items.filter(item => {
  const j = item.json;
  if (!j["Company ID"] || j["Company ID"] === 0 || j["Company ID"] === "") return false;
  if (!j["Product"]) return false;
  if (!j.Month || !j.Year) return false;
  return (
    Number(j.Month) === TARGET_MONTH &&
    Number(j.Year)  === TARGET_YEAR
  );
});

return filtrados;

