    }
  }
];

function normalize(text) {
  return String(text || "")
    .toLowerCase().trim()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

const PRODUCT_MAP = {
  "tour virtual":  0,
  "my photo":      1,
  "my photo cate": 2,
  "default":       3,
  "no aplica":     5
};

return items.map(item => {
  const raw        = item.json.Product || item.json.product || "";
  const normalized = normalize(raw);
  const code       = PRODUCT_MAP[normalized] ?? PRODUCT_MAP["default"];
  return { json: { ...item.json, product_code: code } };
});

